def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            candidates.append((abs(r - h // 2), "row", r))
    for c in range(1, w - 1):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((abs(c - w // 2), "col", c))
    _, axis, i = min(candidates)
    if axis == "row":
        a, b = grid[:i], grid[i + 1:]
    else:
        a = [row[:i] for row in grid]
        b = [row[i + 1:] for row in grid]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    shared = next(iter(common))
    return [[3 if a[r][c] == b[r][c] else shared
             for c in range(len(a[0]))] for r in range(len(a))]
